#include <iostream>
#include <string>

int main()
{
    std::string item{};
    int quantity{};
    double price{};
    std::cin >> item >> quantity >> price;

    std::cout << "Item: " << item << '\n';
    std::cout << "Quantity: " << quantity << '\n';
    std::cout << "Each: " << price << '\n';
    std::cout << "Total: " << quantity * price << '\n';
    return 0;
}
